-- Retention test fixture. NEVER run against production.
-- Real definitions: acceptance tables/RPCs/fingerprints from supabase/migrations (loaded by run_pg_tests.sh);
-- governance views extracted verbatim by extract_real_ddl.py.
-- STUBBED (DDL absent from the repo; reconstructed from every column the real code references):
--   costing_refresh_run, cost_periods, sku_sales_allocation_basis_snapshot,
--   sku_regional_marketing_allocation_basis_snapshot, sku_regional_marketing_expense_allocation_snapshot.
-- Live-catalog equality for these stubs is checked by PREFLIGHT_00_catalog_contract.sql, not assumed.
DO $$ DECLARE r text; BEGIN
 FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('CREATE ROLE %I NOLOGIN',r); END IF;
 END LOOP;
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='sasv_retention_executor') THEN
  CREATE ROLE sasv_retention_executor LOGIN NOINHERIT PASSWORD 'fixture_only'; END IF;
END $$;
CREATE SCHEMA auth; GRANT USAGE ON SCHEMA auth TO anon,authenticated,service_role;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT EXECUTE ON FUNCTION auth.uid() TO anon,authenticated,service_role;
CREATE TABLE public.user_permissions_canonical(user_id uuid,target text,can_view boolean NOT NULL DEFAULT false,can_edit boolean NOT NULL DEFAULT false);
CREATE FUNCTION public.require_permission(p_target text,p_need_edit boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated' USING errcode='28000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_permissions_canonical c WHERE c.user_id=auth.uid() AND c.target=p_target AND c.can_view AND (NOT p_need_edit OR c.can_edit))
 THEN RAISE EXCEPTION 'permission denied' USING errcode='42501'; END IF;
END $$;
GRANT EXECUTE ON FUNCTION public.require_permission(text,boolean) TO authenticated;
CREATE SCHEMA costing; GRANT USAGE ON SCHEMA costing TO authenticated,service_role;
CREATE TABLE costing.costing_refresh_run(id bigint PRIMARY KEY,period_start date NOT NULL,valuation_date date,overall_status text NOT NULL,
 valuation_context_source text,source_trigger text,requested_scope text,requested_at timestamptz,started_at timestamptz,finished_at timestamptz,current_stage_code text);
CREATE TABLE costing.cost_periods(period_start date PRIMARY KEY,status text NOT NULL,valuation_date date,valuation_date_status text);
CREATE TABLE costing.costing_run_designation(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,refresh_run_id bigint NOT NULL REFERENCES costing.costing_refresh_run(id),
 period_start date NOT NULL,designation text NOT NULL CHECK(designation IN('REFERENCE','APPROVED','REVOKED')),designated_by text NOT NULL,designated_by_uid uuid,
 designated_at timestamptz NOT NULL DEFAULT now(),reason text NOT NULL,fingerprint_id bigint);
CREATE TABLE costing.sku_sales_allocation_basis_snapshot(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_start date NOT NULL,valuation_date date NOT NULL,
 refresh_run_id bigint NOT NULL REFERENCES costing.costing_refresh_run(id),sku_id bigint NOT NULL,product_id bigint NOT NULL,product_name text,pack_size numeric,pack_uom text,
 monthly_driver_method text,monthly_driver_source text,monthly_driver_source_month date,monthly_driver_status text,allocation_resolution_status text,allocation_resolution_note text,
 assumption_id bigint,assumption_basis text,default_policy_id bigint,default_policy_scenario text,monthly_allocation_units numeric,monthly_allocation_base_qty numeric);
CREATE TABLE costing.sku_regional_marketing_allocation_basis_snapshot(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_start date NOT NULL,valuation_date date NOT NULL,
 refresh_run_id bigint NOT NULL REFERENCES costing.costing_refresh_run(id),sku_id bigint NOT NULL,product_id bigint NOT NULL,region_code text NOT NULL,
 regional_assumption_id bigint,regional_assumption_basis text,regional_default_policy_id bigint,regional_default_scenario text,regional_default_sales_units numeric,regional_default_assumed_sales_value numeric);
CREATE TABLE costing.sku_regional_marketing_expense_allocation_snapshot(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_start date NOT NULL,valuation_date date NOT NULL,
 refresh_run_id bigint NOT NULL REFERENCES costing.costing_refresh_run(id),regional_basis_snapshot_id bigint NOT NULL REFERENCES costing.sku_regional_marketing_allocation_basis_snapshot(id),
 sku_id bigint NOT NULL,product_id bigint NOT NULL,product_name text,region_code text NOT NULL,regional_basis_source text NOT NULL,regional_basis_status text NOT NULL,
 marketing_value_source text NOT NULL,resolved_product_region_marketing_sales_value numeric,resolved_regional_units numeric,resolved_regional_base_qty numeric,
 marketing_expense_cost_per_sku_region numeric,marketing_expense_allocation_status text NOT NULL);

-- Stubs required only so the REAL costing.fn_w2_run_checks body (extracted) can execute in isolation.
CREATE TABLE costing.costing_run_fingerprint(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,refresh_run_id bigint NOT NULL,purpose text,captured_by text,captured_at timestamptz DEFAULT now(),fingerprint jsonb);
CREATE TABLE costing.fp_stub(refresh_run_id bigint,table_name text,matches boolean);   -- test control for the fingerprint re-verification stub
CREATE FUNCTION costing.fn_verify_run_fingerprint(p_refresh_run_id bigint) RETURNS TABLE(table_name text,captured jsonb,current_value jsonb,matches boolean) LANGUAGE sql AS $$ SELECT s.table_name,NULL::jsonb,NULL::jsonb,s.matches FROM costing.fp_stub s WHERE s.refresh_run_id=p_refresh_run_id $$;
CREATE TABLE costing.v_sku_detailed_cost_sheet_t(refresh_run_id bigint,sku_id bigint,cost_sheet_status text);
CREATE VIEW costing.v_sku_detailed_cost_sheet AS SELECT * FROM costing.v_sku_detailed_cost_sheet_t;
CREATE TABLE costing.costing_period_refresh_authorization(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,period_start date,consumed_by_run_id bigint);
\i :views_file
